function directorAttention(){
 const open=state.maintenance.filter(r=>r.status!=='done'),late=open.filter(r=>r.dueDate&&r.dueDate<today()),blocked=machines.filter(m=>m.status==='repair'),pending=state.shifts.filter(x=>x.status==='pending'),unallocated=unallocatedExpenses(),loss=machines.filter(m=>result(m)<0),stockLow=state.stock.filter(p=>p.qty<p.min),requestsDue=typeof requestList==='function'?requestList().filter(requestNeedsFollowup):[],purchases=(state.purchaseRequests||[]).filter(p=>p.status==='На согласовании');
 const items=[['Просроченные ремонты',late.length,'maintenance'],['Техника без допуска',blocked.length,'maintenance'],['Смены на проверке',pending.length,'shifts'],['Продления заявок (5 ч)',requestsDue.length,'requests'],['Расходы без техники',unallocated.length,'finance'],['Машины с отрицательным результатом',loss.length,'efficiency'],['Запчасти ниже минимума',stockLow.length,'inventory'],['Закупки на согласовании',purchases.length,'procurement']];
 return '<section class="panel padded"><div class="panel-head"><div><h2>Требует решения руководителя</h2><p class="subtitle">Контрольные сигналы по текущим демонстрационным данным</p></div></div><div class="status-cards">'+items.map(([label,count,target])=>'<button class="status-card" data-nav="'+target+'" style="text-align:left;cursor:pointer"><span>'+esc(label)+'</span><strong>'+count+'</strong></button>').join('')+'</div><p class="page-note">Отрицательный результат — выручка минус учтённые прямые расходы, не чистая прибыль. Часы загрузки пока условные.</p></section>';
}
function directorPurchases(){
 state.purchaseRequests??=[];
 return state.purchaseRequests;
}
function directorPurchaseForm(){
 if(role!=='director'&&role!=='mechanic')return;
 showModal('Заявка на закупку', '<form id="purchase-form">'+field('Материал','<input name="item" maxlength="120" required placeholder="Название запчасти">')+'<div class="form-grid">'+field('Количество','<input name="qty" type="number" min="0.01" step="0.01" required>')+field('Ориентировочная стоимость, ₽','<input name="price" type="number" min="0" step="0.01" required>')+'</div>'+field('Техника',machineSelect('machine','M001'))+field('Обоснование','<textarea name="note" maxlength="400" required></textarea>')+formActions('Создать заявку')+'</form>');
 $('#purchase-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),qty=Number(f.get('qty')),price=Number(f.get('price'));if(!Number.isFinite(qty)||qty<=0||!Number.isFinite(price)||price<0)return formError('Проверьте количество и стоимость.');const prev=structuredClone(state);const p={id:uid(),number:'СН-'+String(Date.now()).slice(-6),item:String(f.get('item')).trim(),qty,price,machine:f.get('machine'),note:String(f.get('note')).trim(),status:'На согласовании',at:new Date().toISOString(),history:[{at:new Date().toISOString(),by:roleNames[role],text:'Заявка создана'}]};if(!p.item||!p.note)return formError('Укажите материал и обоснование.');directorPurchases().push(p);if(!persist()){state=prev;return formError('Не удалось сохранить заявку.');}closeModal(false);render();toast('Заявка на закупку создана.');};
}
function directorPurchaseDecision(id){
 if(role!=='director')return;
 const p=directorPurchases().find(x=>x.id===id);if(!p||!['На согласовании','Согласована','Заказана'].includes(p.status))return;
 const options=p.status==='На согласовании'?['Согласована','Отклонена']:p.status==='Согласована'?['Заказана']:['Получена'];
 showModal('Закупка '+p.number,'<p>'+esc(p.item)+' · '+p.qty+' ед. · '+rub(p.price)+'</p><form id="purchase-decision">'+field('Решение','<select name="status">'+options.map(x=>'<option>'+esc(x)+'</option>').join('')+'</select>')+field('Комментарий','<textarea name="note" maxlength="300"></textarea>')+formActions('Сохранить решение')+'</form>');
 $('#purchase-decision').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),next=f.get('status');if(!options.includes(next))return;const prev=structuredClone(state);p.status=next;p.history.push({at:new Date().toISOString(),by:'Руководитель',text:next+' · '+String(f.get('note')||'')});if(!persist()){state=prev;return formError('Не удалось сохранить решение.');}closeModal(false);render();toast('Статус закупки обновлён.');};
}
function procurementPage(){
 const rows=directorPurchases();
 return '<section class="panel padded"><div class="panel-head"><div><h2>Заявки на снабжение</h2><p class="subtitle">Создание и согласование заявок · данные хранятся в браузере</p></div><button class="btn primary" data-purchase-new>Создать заявку</button></div>'+(!rows.length?'<p class="subtitle">Заявок пока нет. Создайте первую заявку на закупку.</p>':'<div class="table-scroll"><table class="data-table"><thead><tr><th>Номер</th><th>Материал</th><th>Техника</th><th>Кол-во</th><th>Сумма</th><th>Статус</th><th>Действие</th></tr></thead><tbody>'+rows.slice().reverse().map(p=>'<tr><td>'+esc(p.number)+'</td><td>'+esc(p.item)+'<span class="cell-note">'+esc(p.note)+'</span></td><td>'+esc(machine(p.machine).name)+'</td><td>'+p.qty+'</td><td>'+rub(p.price)+'</td><td>'+tag(p.status,p.status==='Отклонена'?'red':p.status==='Получена'?'green':'blue')+'</td><td>'+(role==='director'&&['На согласовании','Согласована','Заказана'].includes(p.status)?'<button class="btn small" data-purchase-id="'+esc(p.id)+'">Изменить статус</button>':'—')+'</td></tr>').join('')+'</tbody></table></div>')+'<p class="page-note">Поступление запчастей на склад и финансовые операции пока оформляются отдельно. Согласование закупки не списывает деньги и не меняет остатки автоматически.</p></section>';
}
function financialStats(){const s=overallFinance(),r=s.income-s.expense;return `<section class="stats" aria-label="Финансовые показатели">${metric('Выручка',moneyMetric(s.income),'income',`${operations().filter(o=>o.kind==='income').length} записей о доходах`)}${metric('Все расходы',moneyMetric(s.expense),'expense','Включая общехозяйственные и нераспределённые')}${metric('Результат по всем учтённым расходам',(r<0?`<span class="negative">${moneyMetric(r)}</span>`:moneyMetric(r)),'profit','Выручка за вычетом учтённых расходов',true)}${metric('Маржа по учтённым данным',`${s.income?(r/s.income*100).toFixed(1).replace('.',','):'—'}<span class="stat-unit">%</span>`,'finance','Налоги и амортизация не учтены')}</section>`;}
function operationalStats(){return `<section class="stats">${metric('Всего техники','10','fleet',`${machines.filter(m=>m.status==='work').length} в работе · ${machines.filter(m=>m.status==='repair').length} на ремонте`)}${metric('Активных объектов','3','objects','Строительные площадки')}${metric('Смены на проверке',state.shifts.filter(s=>s.status==='pending').length,'shifts','Ожидают проверки механиком',true)}${metric('Задачи обслуживания',state.maintenance.filter(s=>s.status!=='done').length,'maintenance','Плановое ТО и ремонт')}</section>`;}
function objectChart(){const totals=objects.map(o=>({...o,...sums(machines.filter(m=>m.object===o.id))}));const max=Math.max(...totals.map(o=>o.income),...totals.map(o=>o.expense),1);return `<section class="panel"><div class="panel-head"><div><h2>Экономика объектов</h2><p class="subtitle">Выручка и учтённые расходы</p></div><div class="chart-legend"><span><i class="legend-dot" style="background:#487cf1"></i>Доход</span><span><i class="legend-dot" style="background:#c9d7f5"></i>Расход</span></div></div><div class="object-chart">${totals.map(o=>`<div class="object-bar-row"><div class="bar-title">${esc(o.name)}<small>${machines.filter(m=>m.object===o.id).length} ед. техники</small></div><div class="bar-pair" aria-hidden="true"><div class="bar-track"><div class="bar-fill" style="width:${o.income/max*100}%"></div></div><div class="bar-track"><div class="bar-fill expense" style="width:${o.expense/max*100}%"></div></div></div><div class="bar-value" aria-label="Доход ${rub(o.income)}, расход ${rub(o.expense)}">${compact(o.income)} ₽<br><small>${compact(o.expense)} ₽</small></div></div>`).join('')}</div></section>`;}
function expenseChart(id=null){const ops=id?machineOps(id):operations();const names=[...new Set([...categories,...ops.filter(o=>o.kind==='expense').map(o=>o.category)])];const cats=names.map((name,i)=>({name,color:categoryColors[i%categoryColors.length],value:ops.filter(o=>o.kind==='expense'&&o.category===name).reduce((s,o)=>s+o.amount,0)}));const total=cats.reduce((s,c)=>s+c.value,0);let offset=0;const segments=cats.map(c=>{const size=total?c.value/total*100:0;const svg=`<circle cx="70" cy="70" r="54" fill="none" stroke="${c.color}" stroke-width="16" pathLength="100" stroke-dasharray="${size} ${100-size}" stroke-dashoffset="${-offset}"/>`;offset+=size;return svg;}).join('');return `<section class="panel"><div class="panel-head"><h2>Структура расходов</h2><span class="muted tiny">${cats.length} статей</span></div><div class="donut-row"><div class="donut"><svg viewBox="0 0 140 140" role="img" aria-label="Расходы по категориям"><circle cx="70" cy="70" r="54" stroke="#eff3fa" stroke-width="16" fill="none"/>${segments}</svg><div class="donut-center"><b>${compact(total)}</b><small>рублей за период</small></div></div><div class="donut-legend">${cats.map(c=>`<div title="${esc(c.name)}: ${rub(c.value)}"><span><i class="legend-dot" style="background:${c.color}"></i>${esc(c.name)}</span><b>${total?Math.round(c.value/total*100):0}%</b></div>`).join('')}</div></div></section>`;}
function fleetTable(ms,limit=null){const list=limit?ms.slice(0,limit):ms;return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Техника</th><th>Объект</th><th>Статус</th>${canFinance()?'<th class="num desktop-col">Выручка</th><th class="num desktop-col">Расходы</th><th class="num">Результат</th>':''}<th class="num desktop-col">Загрузка</th><th></th></tr></thead><tbody>${list.map(m=>{const s=sums([m]);return `<tr data-machine="${m.id}"><td><div class="machine-label"><span class="machine-icon">${icon(m.type.includes('кран')?'crane':'fleet')}</span><div><button class="table-link machine-title" data-machine="${m.id}">${esc(m.name)}</button><div class="machine-sub">${m.id} · ${esc(m.type)}</div></div></div></td><td><button class="table-link" data-object="${m.object}">${esc(obj(m.object).name)}</button></td><td>${machineTag(m)}</td>${canFinance()?`<td class="num money desktop-col">${rub(s.income)}</td><td class="num money desktop-col">${rub(s.expense)}</td><td class="num money ${s.income-s.expense>=0?'positive':'negative'}">${rub(s.income-s.expense)}</td>`:''}<td class="num desktop-col"><div class="util"><span class="util-track"><i style="width:${m.hours/m.plan*100}%"></i></span>${Math.round(m.hours/m.plan*100)}%</div></td><td><button class="table-link" data-machine="${m.id}" aria-label="Открыть ${esc(m.name)}">${icon('chevron')}</button></td></tr>`;}).join('')}</tbody></table></div>${!list.length?empty('Техника не найдена','Измените запрос или фильтры.'):''}`;}
function marsUpgradeDashboard(){const total=machines.reduce((a,m)=>a+m.hours,0),planned=machines.reduce((a,m)=>a+m.plan,0),idle=planned-total,rank=machines.map(m=>({m,...sums([m])})).sort((a,b)=>(b.income-b.expense)-(a.income-a.expense));return `<section class="mars-upgrade" aria-label="Оперативный контроль, демонстрационные показатели"><div class="mars-upgrade-title"><div><h2>Оперативный контроль</h2><p class="subtitle">Условные показатели · загрузка по плановым часам, не подтверждённые простои</p></div><span class="tag blue">ДЕМО · ${esc(period)}</span></div><div class="mars-upgrade-kpis"><div><small>Загрузка парка</small><strong>${planned?Math.round(total/planned*100):0}%</strong><span>${total} из ${planned} плановых ч</span></div><div><small>Неотработанные плановые часы</small><strong>${idle} ч</strong><span>Не равны подтверждённым простоям</span></div><div><small>Техника на ремонте</small><strong>${machines.filter(m=>m.status==='repair').length}</strong><span>Требует внимания механика</span></div><div><small>Смены на проверке</small><strong>${state.shifts.filter(x=>x.status==='pending').length}</strong><span>Ожидают решения механика</span></div></div>${canFinance()?`<div class="mars-upgrade-rank"><h3>Финансовый результат по технике · условные данные</h3><div class="mars-upgrade-rank-list">${rank.slice(0,5).map(x=>`<button type="button" data-machine="${x.m.id}"><span>${esc(x.m.name)}</span><b class="${x.income-x.expense<0?'negative':'positive'}">${rub(x.income-x.expense)}</b><span aria-hidden="true">›</span></button>`).join('')}</div></div>`:''}</section>`;}
function efficiencyPage(){
 const rows=machines.map(m=>{
 const ops=machineOps(m.id);
 const income=ops.filter(o=>o.kind==='income').reduce((a,o)=>a+o.amount,0);
 const expense=ops.filter(o=>o.kind==='expense').reduce((a,o)=>a+o.amount,0);
 return {m,income,expense,balance:income-expense};
 }).sort((a,b)=>b.balance-a.balance);
 const total=rows.reduce((a,r)=>({income:a.income+r.income,expense:a.expense+r.expense}),{income:0,expense:0});
 const indirect=unallocatedExpenses().reduce((n,o)=>n+o.amount,0);
 return '<section class="panel padded"><h2>Эффективность техники</h2><p class="subtitle">Демо: финансовые показатели за выбранный период; часы и план из карточек техники — условные, не подтверждены за тот же период.</p><div class="stats"><article class="stat"><div class="stat-label">Выручка</div><div class="stat-value">'+rub(total.income)+'</div></article><article class="stat"><div class="stat-label">Расходы по машинам</div><div class="stat-value">'+rub(total.expense)+'</div></article><article class="stat"><div class="stat-label">Не распределено по технике</div><div class="stat-value">'+rub(indirect)+'</div></article></div><div style="overflow-x:auto"><table class="data-table"><thead><tr><th>Техника</th><th>Выручка</th><th>Расходы</th><th>Результат</th><th>Часы*</th><th>Загрузка*</th><th>Расход/час*</th></tr></thead><tbody>'+rows.map(r=>'<tr><td><button class="btn ghost" data-machine="'+esc(r.m.id)+'">'+esc(r.m.name)+'</button></td><td>'+rub(r.income)+'</td><td>'+rub(r.expense)+'</td><td>'+rub(r.balance)+'</td><td>'+r.m.hours+' / '+r.m.plan+'</td><td>'+(r.m.plan?Math.round(r.m.hours/r.m.plan*100)+'%':'—')+'</td><td>'+(r.m.hours?rub(Math.round(r.expense/r.m.hours)):'—')+'</td></tr>').join('')+'</tbody></table></div><p class="subtitle">* Оценочные показатели. Нераспределённые и общехозяйственные расходы показаны отдельно и не включены в результат конкретных машин. Амортизация и налоги не учтены. Это не полная себестоимость машино-часа.</p></section>';
}
function dashboardPage(){if(role==='dispatcher')return managerOverview()+repairAttention()+fleetTable(machines,5);return (role==='director'?directorAttention()+'<section class="panel padded"><div class="panel-head"><div><h2>Эффективность техники</h2><p class="subtitle">Сравнение выручки, расходов и загрузки по каждой машине</p></div><button class="btn primary" data-nav="efficiency">Открыть аналитику →</button></div></section>':'')+marsDashboardBase();}
function marsDashboardBase(){const pending=state.shifts.filter(s=>s.status==='pending').length;return `${repairAttention()}${marsUpgradeDashboard()}${canFinance()?financialStats():operationalStats()}${canFinance()?`<div class="charts-row">${objectChart()}${expenseChart()}</div>`:''}<section class="panel"><div class="panel-head"><div><h2>Обзор парка <span class="tag gray">10 единиц</span></h2><p class="subtitle">Состояние и результат работы техники</p></div><button class="btn ghost" data-nav="fleet">Весь парк ${icon('arrow')}</button></div>${fleetTable(machines,5)}<div class="fleet-bar"><span><span class="status-dot"></span><strong>${machines.filter(m=>m.status==='work').length}</strong> в работе</span><span><span class="status-dot" style="background:#d4a75a"></span><strong>${machines.filter(m=>m.status==='repair').length}</strong> на ремонте</span><span>На 3 объектах</span></div></section><div class="attention-row">${allowed[role].includes('shifts')?`<button class="attention" data-nav="shifts"><span class="icon-wrap">${icon('shifts')}</span><span><b>${pending} смены на проверке</b><small>Проверьте часы и замечания</small></span>${icon('chevron')}</button>`:''}${allowed[role].includes('maintenance')?`<button class="attention" data-nav="maintenance"><span class="icon-wrap">${icon('maintenance')}</span><span><b>${state.maintenance.some(s=>s.machine==='M008'&&s.status!=='done')?'JCB 531-70 · ремонт':'План обслуживания'}</b><small>${state.maintenance.filter(s=>s.status!=='done').length} открытых задач</small></span>${icon('chevron')}</button>`:''}<button class="attention" data-nav="${allowed[role].includes('inventory')?'inventory':'settings'}"><span class="icon-wrap">${icon(allowed[role].includes('inventory')?'inventory':'lock')}</span><span><b>${allowed[role].includes('inventory')?'Запас воздушных фильтров':'Демонстрационный режим'}</b><small>${allowed[role].includes('inventory')?'1 шт. при минимуме 2 шт.':'Изменения хранятся в этом браузере'}</small></span>${icon('chevron')}</button></div>`;}
function empty(title,desc){return `<div class="empty-state">${icon('search')}<b>${esc(title)}</b><p>${esc(desc)}</p></div>`;}
const objectOptions=()=>`<option value="all">Все объекты</option>${objects.map(o=>`<option value="${o.id}" ${objectFilter===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}`;
function fleetPage(){const q=query.toLocaleLowerCase('ru');const ms=visibleMachines().filter(m=>(objectFilter==='all'||m.object===objectFilter)&&(statusFilter==='all'||m.status===statusFilter)&&(m.name+' '+m.type+' '+m.id+' '+obj(m.object).name).toLocaleLowerCase('ru').includes(q));return `<div class="filter-row"><input id="fleet-search" type="search" placeholder="Название, инвентарный номер или объект" aria-label="Поиск техники" value="${esc(query)}"><select id="object-filter" aria-label="Фильтр по объекту">${objectOptions()}</select><select id="status-filter" aria-label="Фильтр по состоянию"><option value="all">Все состояния</option><option value="work" ${statusFilter==='work'?'selected':''}>В работе</option><option value="repair" ${statusFilter==='repair'?'selected':''}>На ремонте</option></select><span class="count">Найдено: ${ms.length} из 10</span></div><section class="panel">${fleetTable(ms)}</section><p class="page-note">Загрузка: условные отработанные часы / плановые часы за один демонстрационный месяц.</p>`;}
function buildingArt(){return '<svg class="building-art" viewBox="0 0 170 120" aria-hidden="true"><path d="M20 120V40h42v80M68 120V8h45v112M121 120V58h35v62" fill="#bdcee8"/><path d="M24 40l38-15v15M72 8l41 15V8" fill="#c9d7ec"/><path d="M29 53h10v11H29zM46 53h10v11H46zM29 75h10v11H29zM46 75h10v11H46zM79 29h9v11h-9zM96 29h9v11h-9zM79 51h9v11h-9zM96 51h9v11h-9zM79 73h9v11h-9zM96 73h9v11h-9zM130 70h8v10h-8zM144 70h8v10h-8zM130 91h8v10h-8zM144 91h8v10h-8z" fill="#eaf0fa"/></svg>';}
function objectsPage(){return `<div class="object-grid">${objects.map((o,i)=>{const ms=machines.filter(m=>m.object===o.id),s=sums(ms);return `<section class="object-card"><div class="object-card-top">${tag('Объект 0'+(i+1),'blue')}${buildingArt()}<h2>${esc(o.name)}</h2></div><div class="object-card-body"><div class="muted tiny">${esc(o.address)} · условный адрес</div><div class="object-metrics"><div><span>Единиц техники</span><b>${ms.length}</b></div>${canFinance()?`<div><span>Выручка</span><b class="money">${rub(s.income)}</b></div><div><span>Расходы</span><b class="money">${rub(s.expense)}</b></div><div><span>Результат</span><b class="money ${s.income-s.expense>=0?'positive':'negative'}">${rub(s.income-s.expense)}</b></div>`:`<div><span>В работе</span><b>${ms.filter(m=>m.status==='work').length} единиц</b></div>`}</div><div class="object-machines">${ms.map(m=>`<span>${m.id}</span>`).join('')}</div><button class="btn" data-object="${o.id}">Техника на объекте ${icon('arrow')}</button></div></section>`;}).join('')}</div>`;}
function financePageHtml(){const q=query.toLocaleLowerCase('ru');const rows=operations().filter(o=>(kindFilter==='all'||o.kind===kindFilter)&&(objectFilter==='all'||(machines.some(m=>m.id===o.machine)&&machine(o.machine).object===objectFilter))&&((machines.some(m=>m.id===o.machine)?machine(o.machine).name:'Без техники')+' '+o.category+' '+(o.note||'')+' '+(o.machine||'')).toLocaleLowerCase('ru').includes(q)).sort((a,b)=>b.date.localeCompare(a.date)||Number(a.seed)-Number(b.seed));const pageSize=15,maxPage=Math.max(0,Math.ceil(rows.length/pageSize)-1);financePage=Math.min(financePage,maxPage);return `${financialStats()}<div class="info-note"><strong>Контроль распределения:</strong> ${unallocatedExpenses().length} расходов без техники на сумму ${rub(unallocatedExpenses().reduce((n,o)=>n+o.amount,0))}. Они входят в общий результат, но не в себестоимость конкретной машины.</div><div class="filter-row"><input id="finance-search" type="search" placeholder="Поиск по технике, статье, комментарию" aria-label="Поиск операций" value="${esc(query)}"><select id="kind-filter" aria-label="Тип операции"><option value="all">Все операции</option><option value="income" ${kindFilter==='income'?'selected':''}>Доходы</option><option value="expense" ${kindFilter==='expense'?'selected':''}>Расходы</option></select><select id="object-filter" aria-label="Объект">${objectOptions()}</select></div><section class="panel"><div class="panel-head"><h2>Журнал операций</h2><button class="btn ghost" data-export="finance">${icon('down')}CSV для Excel</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Дата</th><th>Техника</th><th>Статья</th><th class="desktop-col">Объект</th><th class="num">Сумма</th><th></th></tr></thead><tbody>${rows.slice(financePage*pageSize,(financePage+1)*pageSize).map(o=>`<tr><td>${dateText(o.date)}${o.seed?'<span class="cell-note">Месячная демосумма</span>':''}</td><td><button class="table-link machine-title" data-machine="${o.machine}">${esc(machines.some(m=>m.id===o.machine)?machine(o.machine).name:(o.allocation==='overhead'?'Общехозяйственные':'Не распределено'))}</button><span class="cell-note">${esc(o.machine||'Без техники')}</span></td><td>${esc(o.category)}<span class="cell-note" title="${esc(o.note)}">${esc(o.note)}</span></td><td class="desktop-col">${machines.some(m=>m.id===o.machine)?esc(obj(machine(o.machine).object).name):'—'}</td><td class="num money ${o.kind==='income'?'positive':''}">${o.kind==='income'?'+':'−'}${rub(o.amount)}</td><td>${!o.seed&&!o.sourceRepair&&o.source!=='excel-demo'?`<button class="table-link negative" data-delete-operation="${o.id}" aria-label="Удалить операцию ${esc(o.category)}">${icon('close')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Операции не найдены','Попробуйте другой период или фильтр.'):''}<div class="table-footer"><span>${rows.length} операций · ${financePage+1} / ${maxPage+1}</span><div class="cell-actions"><button class="btn small" data-page="${financePage-1}" ${!financePage?'disabled':''}>Назад</button><button class="btn small" data-page="${financePage+1}" ${financePage===maxPage?'disabled':''}>Далее</button></div></div></section><div class="info-note"><strong>Как читать показатели.</strong> Финансовый результат = выручка − учтённые расходы. Это не чистая прибыль: налоги, амортизация, проценты по кредитам и общие расходы компании не заданы. Стартовые записи — условные месячные суммы, а не фактические платежи.</div>`;}
function shiftsPage(){const all=visibleShifts(),rows=all.filter(s=>shiftFilter==='all'||s.status===shiftFilter).slice().sort((a,b)=>b.date.localeCompare(a.date));return `<div class="status-cards">${[['pending','На проверке'],['approved','Утверждены'],['returned','Возвращены']].map(([s,label])=>`<div class="status-card"><span>${label}</span><strong>${all.filter(x=>x.status===s).length}</strong></div>`).join('')}</div><div class="tabs" role="group" aria-label="Состояние смены">${[['all','Все смены'],['pending','На проверке'],['approved','Утверждены'],['returned','Возвращены']].map(([id,t])=>`<button class="tab ${shiftFilter===id?'active':''}" data-shift-filter="${id}">${t}</button>`).join('')}</div><section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Дата / машинист</th><th>Техника</th><th>Часы</th><th class="desktop-col">Счётчик, м/ч</th><th>Состояние</th><th>Статус</th><th>Действия</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${dateText(s.date)}<span class="cell-note">${esc(machine(s.machine).operator)}</span></td><td><button class="table-link machine-title" data-machine="${s.machine}">${esc(machine(s.machine).name)}</button><span class="cell-note">${esc(obj(machine(s.machine).object).name)}</span></td><td class="money">${s.hours} ч</td><td class="desktop-col">${s.meter.toLocaleString('ru-RU')}</td><td>${tag(s.condition==='ok'?'Исправна':'Есть замечание',s.condition==='ok'?'green':'orange')}<span class="cell-note" title="${esc(s.note)}">${esc(s.note)}</span>${s.returnNote?`<span class="cell-note negative">${esc(s.returnNote)}</span>`:''}</td><td>${shiftTag(s)}${s.photos?.length?`<span class="cell-note">${s.photos.length} фото</span>`:''}${s.repairId?`<button class="table-link cell-note" data-repair="${s.repairId}">Заявка на ремонт</button>`:''}</td><td><div class="cell-actions">${s.status==='pending'&&canApprove()?`<button class="btn primary small" data-approve="${s.id}">Утвердить</button><button class="btn small" data-return="${s.id}">Вернуть</button>`:s.status==='returned'&&role!=='dispatcher'?`<button class="btn small" data-edit-shift="${s.id}">Исправить</button>`:s.status==='approved'?`<button class="btn small" data-waybill="${s.id}">${icon('waybills')}Лист</button>${canEditRecords()?`<button class="btn small" data-record-edit="${s.id}">Изменить</button>`:''}`:'<span class="muted tiny">Ожидает проверки</span>'}</div></td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Смен пока нет','Закройте смену, чтобы передать её на проверку.'):''}</section><div class="info-note"><strong>Порядок работы:</strong> механик вносит смену → механик или руководитель проверяет → утверждённые часы попадают в табель и черновик путевого листа. Утверждение смены не создаёт финансовую операцию автоматически.</div>${role==='operator'?'<p class="page-note">В режиме машиниста показан пример рабочего места Алексея Морозова, Bobcat S650.</p>':''}`;}
function waybillsPage(){const rows=visibleShifts().filter(s=>s.status==='approved');return `<section class="panel"><div class="panel-head"><h2>Черновики путевых листов</h2>${tag(rows.length+' документов','blue')}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Документ</th><th>Дата</th><th>Техника</th><th class="desktop-col">Машинист</th><th>Часы</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><button class="table-link machine-title" data-waybill="${s.id}">${esc(s.waybill)}</button><span class="cell-note">${esc(obj(machine(s.machine).object).name)}</span></td><td>${dateText(s.date)}</td><td>${esc(machine(s.machine).name)}</td><td class="desktop-col">${esc(machine(s.machine).operator)}</td><td>${s.hours} ч</td><td><button class="btn small" data-waybill="${s.id}">Открыть</button>${canEditRecords()?`<button class="btn small" data-record-edit="${s.id}">Изменить</button>`:''}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Нет утверждённых смен','После утверждения смены здесь появится черновик документа.'):''}</section><p class="page-note">Черновик показывает связь смены с документом. Для использования в компании нужны согласованная форма, обязательные реквизиты и ответственные за подписание.</p>`;}
function timesheetsPage(){const shifts=visibleShifts().filter(s=>s.status==='approved');const ms=visibleMachines().filter(m=>shifts.some(s=>s.machine===m.id));return `<div class="status-cards"><div class="status-card"><span>Утверждённые смены</span><strong>${shifts.length}</strong></div><div class="status-card"><span>Всего часов</span><strong>${shifts.reduce((n,s)=>n+s.hours,0)}</strong></div><div class="status-card"><span>Машинистов</span><strong>${ms.length}</strong></div></div><section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Машинист</th><th>Техника</th><th>Смены</th><th class="num">Часы</th><th class="desktop-col">Объект</th></tr></thead><tbody>${ms.map(m=>{const ss=shifts.filter(s=>s.machine===m.id);return `<tr><td class="machine-title">${esc(m.operator)}</td><td>${esc(m.name)}</td><td>${ss.length}</td><td class="num">${ss.reduce((n,s)=>n+s.hours,0)} ч</td><td class="desktop-col">${esc(obj(m.object).name)}</td></tr>`;}).join('')}</tbody></table></div>${canEditRecords()?`<div class="section-gap"><h3>Корректировка табеля по сменам</h3>${shifts.map(s=>`<button class="btn small" data-record-edit="${s.id}">${dateText(s.date)} · ${esc(machine(s.machine).name)} · ${s.hours} ч — изменить</button>`).join(' ')}</div>`:''}${!ms.length?empty('Табель ещё пуст','Часы попадут в табель после утверждения смен.'):''}</section>`;}
function maintenancePage(){return workshopPage();}
function inventoryPage(){return `<section class="panel"><div class="panel-head"><h2>Остатки на складе</h2><span class="muted tiny">${state.stock.length} наименований</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Наименование</th><th>Артикул</th><th class="num">Остаток</th><th class="num">Минимум</th><th>Состояние запаса</th></tr></thead><tbody>${state.stock.map(p=>`<tr><td class="machine-title">${esc(p.name)}</td><td>${esc(p.sku)}</td><td class="num">${p.qty.toLocaleString('ru-RU')} ${esc(p.unit)}</td><td class="num">${p.min} ${esc(p.unit)}</td><td>${tag(p.qty<p.min?'Пополнить':'В норме',p.qty<p.min?'orange':'green')}</td></tr>`).join('')}</tbody></table></div></section><section class="panel section-gap"><div class="panel-head"><h2>Последние движения</h2></div>${state.stockMoves.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Дата</th><th>Запчасть</th><th>Операция</th><th class="num">Количество</th><th>Назначение</th></tr></thead><tbody>${state.stockMoves.slice().reverse().slice(0,15).map(s=>`<tr><td>${dateText(s.date)}</td><td>${esc(state.stock.find(p=>p.id===s.part)?.name)}</td><td>${tag(s.kind==='receipt'?'Поступление':'Выдача',s.kind==='receipt'?'green':'blue')}</td><td class="num">${s.kind==='receipt'?'+':'−'}${s.qty}</td><td>${s.machine?esc(machine(s.machine).name):'Склад'}<span class="cell-note">${esc(s.note)}</span></td></tr>`).join('')}</tbody></table></div>`:empty('Движений пока нет','Добавьте поступление или выдачу запчастей.')}</section>`;}
function reportsPage(){const cards=[...(canFinance()?[['finance','Финансовый журнал','Все доходы и расходы за выбранный период, с привязкой к технике и объектам.','finance'],['fleet','Экономика техники','Выручка, расходы, результат и маржа для каждой единицы парка.','fleet']]:[]),['timesheets','Табель машинистов','Свод по утверждённым сменам и отработанным часам.','timesheets'],['waybills','Реестр путевых листов','Список черновиков, сформированных по утверждённым сменам.','waybills']];return `<div class="report-grid">${cards.map(([type,title,desc,symbol])=>`<section class="report-card"><div class="report-icon">${icon(symbol)}</div><h2>${title}</h2><p>${desc}</p><button class="btn" data-export="${type}">${icon('down')}Скачать CSV</button></section>`).join('')}</div><p class="page-note">Формат CSV с разделителем «;» и кодировкой UTF-8 подходит для открытия в Excel. В выгрузке используются текущий период и демонстрационные данные.</p>`;}
function directoriesPage(){return `<div class="settings-grid"><section class="panel"><h2>Статьи расходов</h2><p class="subtitle">Используются при добавлении операций</p><ul class="directory-list section-gap">${categories.map((c,i)=>`<li>${esc(c)}<small>Р-${String(i+1).padStart(2,'0')}</small></li>`).join('')}</ul></section><section class="panel"><h2>Состав парка</h2><p class="subtitle">Классы техники в демонстрации</p><ul class="directory-list section-gap">${[...new Set(machines.map(m=>m.type))].map(t=>`<li>${esc(t)}<small>${machines.filter(m=>m.type===t).length} ед.</small></li>`).join('')}</ul></section><section class="panel"><h2>Объекты</h2><ul class="directory-list section-gap">${objects.map(o=>`<li>${esc(o.name)}<small>${machines.filter(m=>m.object===o.id).length} ед.</small></li>`).join('')}</ul></section><section class="panel"><h2>Роли</h2><ul class="directory-list section-gap">${Object.values(roleNames).map(t=>`<li>${t}<small>Демо</small></li>`).join('')}</ul><p class="page-note">Переключение в верхней панели показывает интерфейс роли. Это не авторизация сотрудников.</p></section></div>`;}
function settingsPage(){return `<div class="settings-grid"><section class="panel"><h2>Рабочее пространство</h2><div class="settings-row"><span>Компания</span><b>ООО «МонАрх и М»</b></div><div class="settings-row"><span>Версия</span>${tag('Демонстрационная','blue')}</div><div class="settings-row"><span>Режим просмотра</span><b>${roleNames[role]}</b></div><div class="settings-row"><span>Валюта</span><b>Российский рубль · ₽</b></div></section><section class="panel"><h2>Данные и интеграции</h2><div class="settings-row"><span>Хранилище браузера</span>${tag(storageAvailable?'Доступно':'Недоступно',storageAvailable?'green':'orange')}</div><div class="settings-row"><span>Общая база данных</span>${tag('Не подключена','gray')}</div><div class="settings-row"><span>Интеграция с 1С</span>${tag('Не подключена','gray')}</div><div class="settings-row"><span>Доступ сотрудников</span>${tag('Демонстрация ролей','blue')}</div></section><section class="panel"><h2>Сохранить изменения</h2><p class="page-note">Скачайте JSON со своими добавленными операциями, сменами и движениями склада. Условный стартовый парк уже встроен в демоверсию.</p><button class="btn" data-action="backup">${icon('down')}Скачать данные JSON</button></section>${role==='director'?`<section class="panel"><h2>Начать демонстрацию заново</h2><p class="page-note">Удалить добавленные в этом браузере записи и восстановить исходные демонстрационные данные.</p><button class="btn danger" data-action="reset">${icon('refresh')}Сбросить демоданные</button></section>`:''}</div><div class="info-note"><strong>Следующий этап внедрения:</strong> согласовать структуру данных с бухгалтерией, подключить 1С и общую базу, настроить настоящие учётные записи и права сотрудников. Данные между устройствами пока не синхронизируются.</div>`;}
function morePage(){return `<div class="more-grid">${nav.filter(n=>allowed[role].includes(n[0])).map(([id,label,symbol])=>`<button class="more-card" data-nav="${id}">${icon(symbol)}${label}</button>`).join('')}</div>`;}
function updatePage(){const el=$('#page-content');const views={fleet:fleetPage,finance:financePageHtml,shifts:shiftsPage,maintenance:maintenancePage};if(!views[view])return render();el.innerHTML=views[view]();bindContentEvents();}
function bindPageEvents(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));$('#role').onchange=e=>{const selected=e.target.value;if(selected.startsWith('dispatcher:')){role='dispatcher';localStorage.setItem('mars-demo-manager',selected.slice('dispatcher:'.length));}else role=selected;view=allowed[role][0];closeModal(false);render();toast(role==='dispatcher'?'Демо-кабинет: '+currentManager():'Режим просмотра: '+roleNames[role]);};$('#period')?.addEventListener('change',e=>{period=e.target.value;financePage=0;render();});$('#global-search-form')?.addEventListener('submit',e=>{e.preventDefault();const q=$('#global-search').value.trim();if(!q)return;view='fleet';query=q;objectFilter='all';statusFilter='all';render();});bindContentEvents();}
function bindContentEvents(){if(view==='accountant')accountantBind();document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelectorAll('[data-machine]').forEach(b=>b.onclick=e=>{e.stopPropagation();openMachine(b.dataset.machine);});document.querySelectorAll('[data-object]').forEach(b=>b.onclick=e=>{e.stopPropagation();view='fleet';objectFilter=b.dataset.object;query='';statusFilter='all';render();window.scrollTo({top:0,behavior:'auto'});});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportData(b.dataset.export));document.querySelectorAll('[data-shift-filter]').forEach(b=>b.onclick=()=>{shiftFilter=b.dataset.shiftFilter;updatePage();});document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>approveShift(b.dataset.approve));document.querySelectorAll('[data-return]').forEach(b=>b.onclick=()=>returnShiftModal(b.dataset.return));document.querySelectorAll('[data-edit-shift]').forEach(b=>b.onclick=()=>shiftModal(b.dataset.editShift));document.querySelectorAll('[data-request-open]').forEach(b=>b.onclick=()=>requestModal(b.dataset.requestOpen));document.querySelectorAll('[data-waybill]').forEach(b=>b.onclick=()=>waybillModal(b.dataset.waybill));document.querySelectorAll('[data-record-edit]').forEach(b=>b.onclick=()=>recordEditModal(b.dataset.recordEdit));document.querySelectorAll('[data-service-done]').forEach(b=>b.onclick=()=>completeService(b.dataset.serviceDone));document.querySelectorAll('[data-delete-operation]').forEach(b=>b.onclick=()=>deleteOperationModal(b.dataset.deleteOperation));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{financePage=Number(b.dataset.page);updatePage();});for(const name of ['fleet-search','finance-search'])$('#'+name)?.addEventListener('input',e=>{query=e.target.value;financePage=0;const pos=e.target.selectionStart;updatePage();const input=$('#'+name);input.focus();input.setSelectionRange(pos,pos);});$('#object-filter')?.addEventListener('change',e=>{objectFilter=e.target.value;financePage=0;updatePage();});$('#status-filter')?.addEventListener('change',e=>{statusFilter=e.target.value;updatePage();});$('#kind-filter')?.addEventListener('change',e=>{kindFilter=e.target.value;financePage=0;updatePage();});bindWorkshopEvents();document.querySelectorAll('[data-purchase-new]').forEach(b=>b.onclick=directorPurchaseForm);document.querySelectorAll('[data-purchase-id]').forEach(b=>b.onclick=()=>directorPurchaseDecision(b.dataset.purchaseId));}
function handleAction(action){if(action==='add-operation'&&canFinance())operationModal();if(action==='add-request')requestModal();if(action==='add-shift'&&role!=='dispatcher')shiftModal();if(action==='add-service'&&role!=='dispatcher')serviceModal();if(action==='stock-move')stockModal();if(action==='backup'){download('monarch-im-demo-data.json',JSON.stringify({company:'ООО «МонАрх и М»',exportedAt:new Date().toISOString(),demo:true,...state},null,2),'application/json');toast('Файл данных скачан');}if(action==='reset'&&role==='director')resetModal();}
function showModal(title,html,wide=false){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-top"><h2 id="modal-title">${esc(title)}</h2><button class="close-button" data-close-modal aria-label="Закрыть">${icon('close')}</button></div><div class="modal-content">${html}</div></section></div>`;document.body.style.overflow='hidden';$('.modal').focus();$('[data-close-modal]').onclick=()=>closeModal();$('.modal-overlay').onclick=e=>{if(e.target===$('.modal-overlay'))closeModal();};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal());}
function closeModal(restore=true){$('#modal-root').innerHTML='';document.body.style.overflow='';if(restore&&modalFocus?.isConnected)modalFocus.focus();}
const machineSelect=(name='machine',selected='M001',ms=machines)=>`<select name="${name}" required>${ms.map(m=>`<option value="${m.id}" ${selected===m.id?'selected':''}>${esc(m.name)} · ${m.id}</option>`).join('')}</select>`;
const field=(label,control)=>`<div class="field"><label>${label}${control}</label></div>`;
const formActions=(text='Сохранить')=>`<div class="error-text" id="form-error" role="alert"></div><div class="modal-actions"><button class="btn" type="button" data-close>Отмена</button><button class="btn primary" type="submit">${text}</button></div>`;
function formError(text){$('#form-error').textContent=text;}
function dateInPeriod(d){const month=d.slice(0,7);if(monthNames[month])period=month;else period='all';}
function operationModal(id='M001'){showModal('Новая финансовая операция',`<form id="operation-form">${field('Техника',machineSelect('machine',id))}<div class="form-grid">${field('Тип операции','<select name="kind" id="operation-kind"><option value="expense">Расход</option><option value="income">Доход</option></select>')}${field('Дата',`<input type="date" name="date" required value="${today()}">`)}</div><div class="field section-gap"><label>Статья<select name="category" id="operation-category">${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div>${field('Сумма, ₽','<input name="amount" type="number" min="0.01" step="0.01" max="9999999999" required inputmode="decimal" placeholder="Например, 12 500">')}${field('Комментарий','<textarea name="note" maxlength="300" placeholder="За что произведена оплата"></textarea>')}${formActions()}<p class="form-hint">Запись сохраняется в этом браузере и сразу учитывается в показателях.</p></form>`);$('#operation-kind').onchange=e=>{$('#operation-category').innerHTML=(e.target.value==='income'?incomeCategories:categories).map(c=>`<option>${esc(c)}</option>`).join('');};$('#operation-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),amount=Number(f.get('amount'));if(!Number.isFinite(amount)||amount<=0)return formError('Укажите сумму больше нуля.');const record={id:uid(),machine:f.get('machine'),kind:f.get('kind'),category:f.get('category'),date:f.get('date'),amount:Math.round(amount*100)/100,note:f.get('note').trim()};const previous=structuredClone(state);state.operations.push(record);const saved=persist();if(!saved){state=previous;return formError('Операция не сохранена.');}dateInPeriod(record.date);closeModal(false);render();if(saved)toast('Операция добавлена. Показатели пересчитаны.');};}
function openMachine(id){openMachinePassport(id);}
function shiftModal(editId=null){if(role==='dispatcher')return;const existing=state.shifts.find(s=>s.id===editId);if(editId&&(!existing||existing.status!=='returned'))return;const m=machine(existing?.machine||'M001');showModal(existing?'Исправить смену':'Закрытие смены',`<form id="shift-form">${field('Техника',machineSelect('machine',m.id,role==='operator'?machines.slice(0,1):machines))}<div class="form-grid">${field('Дата смены',`<input type="date" name="date" value="${existing?.date||today()}" max="${today()}" required>`) }${field('Отработано часов',`<input type="number" name="hours" value="${existing?.hours||8}" min="0.5" max="24" step="0.5" required inputmode="decimal">`)}</div><div class="field section-gap"><label>Показание счётчика, моточасы<input type="number" name="meter" id="shift-meter" value="${existing?.meter??m.meter+8}" min="${m.meter}" step="0.1" required inputmode="decimal"></label></div>${field('Состояние техники',`<select name="condition"><option value="ok" ${existing?.condition==='ok'?'selected':''}>Исправна, замечаний нет</option><option value="issue" ${existing?.condition==='issue'?'selected':''}>Есть неисправность или замечание</option></select>`)}${field('Комментарий машиниста',`<textarea name="note" maxlength="300" placeholder="Что сделано, есть ли замечания">${esc(existing?.note||'')}</textarea>`)}${photoPicker('shift-photos')}${formActions('Отправить на проверку')}<p class="form-hint">При замечании заявка на ремонт создаётся сразу. Менеджер отдельно утверждает часы для табеля и черновика путевого листа.</p></form>`);const shiftPhotos=attachPhotoPicker('shift-photos',existing?.photos||[]);$('#shift-form select[name=machine]').onchange=e=>{$('#shift-meter').value=machine(e.target.value).meter+8;$('#shift-meter').min=machine(e.target.value).meter;};$('#shift-form').onsubmit=e=>{e.preventDefault();if(shiftPhotos.busy)return formError('Дождитесь подготовки фотографий.');const f=new FormData(e.target),id=f.get('machine'),hours=Number(f.get('hours')),meter=Number(f.get('meter')),condition=f.get('condition'),note=f.get('note').trim(),date=f.get('date');const previous=Math.max(machine(id).meter,...state.shifts.filter(s=>s.machine===id&&s.status==='approved'&&s.date<=date).map(s=>s.meter));if(hours<=0||hours>24||!Number.isFinite(hours))return formError('Продолжительность смены должна быть от 0,5 до 24 часов.');if(!Number.isFinite(meter)||meter<previous)return formError('Показание счётчика не может быть меньше предыдущего: '+previous+' м/ч.');if(date>today())return formError('Нельзя закрыть смену за будущую дату.');if(condition==='issue'&&!note)return formError('Опишите замечание к технике.');if(state.shifts.some(s=>s.id!==editId&&s.machine===id&&s.date===date&&s.status!=='returned'))return formError('Для этой техники на эту дату смена уже создана.');const previousState=structuredClone(state);const record={id:editId||uid(),machine:id,date,hours,meter,condition,note,photos:shiftPhotos.photos,status:'pending'};if(existing)Object.assign(existing,record,{returnNote:''});else state.shifts.push(record);if(condition==='issue'){let repair=state.maintenance.find(r=>r.sourceShift===record.id);if(!repair){repair=newRepairRecord({machine:id,type:'Замечание машиниста',note,date,dueDate:today(),priority:'high',photos:shiftPhotos.photos,sourceShift:record.id,blocking:false});state.maintenance.push(repair);}else if(repair.status!=='done'){repair.note=note;repair.photos=shiftPhotos.photos;recordRepairEvent(repair,'Машинист уточнил замечание к смене');}const savedShift=state.shifts.find(s=>s.id===record.id);savedShift.repairId=repair.id;}const saved=saveWorkshop(previousState);if(!saved)return;dateInPeriod(date);shiftFilter='all';closeModal(false);view='shifts';render();if(saved)toast(condition==='issue'?'Смена отправлена. Заявка на ремонт создана.':'Смена отправлена на проверку менеджеру.');};}
function recordEditModal(id){
 if(!canEditRecords())return;
 const s=state.shifts.find(x=>x.id===id);
 if(!s||s.status!=='approved')return;
 const history=auditTrail().filter(x=>x.shiftId===id).slice().reverse();
 showModal('Корректировка смены, путевого листа и табеля',`<form id="record-edit-form">
 <p class="page-note">Изменения часов автоматически отражаются в табеле и черновике путевого листа. Все корректировки сохраняются в журнале.</p>
 <div class="form-grid"><label class="field">Отработано, ч<input name="hours" type="number" min="0" max="24" step="0.5" required value="${s.hours}"></label><label class="field">Моточасы / счётчик<input name="meter" type="number" min="0" step="0.1" required value="${s.meter}"></label></div>
 <label class="field">Комментарий к смене<textarea name="note" maxlength="500">${esc(s.note||'')}</textarea></label>
 <label class="field">Причина корректировки (обязательно)<textarea name="reason" maxlength="500" required></textarea></label>
 <div class="modal-actions"><button type="button" class="btn" data-close>Отмена</button><button type="submit" class="btn primary">Сохранить исправления</button></div></form>
 <h3 class="section-gap">Журнал изменений</h3>${history.length?history.map(x=>`<p class="page-note"><strong>${esc(x.at)} · ${esc(x.actor)}</strong><br>Причина: ${esc(x.reason)}<br>Было: ${esc(x.before.hours)} ч / ${esc(x.before.meter)} м/ч; стало: ${esc(x.after.hours)} ч / ${esc(x.after.meter)} м/ч</p>`).join(''):'<p class="page-note">Корректировок пока нет.</p>'}`,true);
 document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal());
 $('#record-edit-form').onsubmit=e=>{
 e.preventDefault();if(!canEditRecords())return;
 const data=new FormData(e.target),hours=Number(data.get('hours')),meter=Number(data.get('meter')),note=String(data.get('note')||'').trim(),reason=String(data.get('reason')||'').trim();
 if(!Number.isFinite(hours)||hours<0||hours>24||!Number.isFinite(meter)||meter<0||!reason)return formError('Проверьте часы, счётчик и причину изменения.');
 const before={hours:s.hours,meter:s.meter,note:s.note||''};
 if(before.hours===hours&&before.meter===meter&&before.note===note)return formError('Нет изменений для сохранения.');
 s.hours=hours;s.meter=meter;s.note=note;
 auditTrail().push({shiftId:id,at:new Date().toISOString(),actor:roleNames[role],reason,before,after:{hours,meter,note}});
 const saved=persist();closeModal(false);render();if(saved)toast('Исправления сохранены в смене, табеле и путевом листе.');
 };
}

const demoManagers=['Алексей Иванов','Дмитрий Петров'];
const currentManager=()=>localStorage.getItem('mars-demo-manager')||demoManagers[0];
const requestList=()=>Array.isArray(state.equipmentRequests)?state.equipmentRequests:(state.equipmentRequests=[]);
const requestIsActive=r=>r.status!=='Отменена'&&!r.releaseConfirmed;
const requestNeedsFollowup=r=>requestIsActive(r)&&r.status!=='Завершена'&&r.items.some(x=>{const end=new Date(x.end);return Number.isFinite(end.getTime())&&end.getTime()<=Date.now()+5*60*60*1000;})&&!['Продление согласовано','Завершение согласовано'].includes(r.followup);
function managerOverview(){const rows=requestList(),active=rows.filter(requestIsActive),free=machines.filter(m=>m.status!=='repair'&&!active.some(r=>r.items.some(x=>x.machine===m.id))),pending=rows.filter(requestNeedsFollowup);return '<section class="panel padded"><h2>Рабочий стол менеджера</h2><div class="status-cards"><div class="status-card"><span>Свободно техники</span><strong>'+free.length+'</strong></div><div class="status-card"><span>На ремонте</span><strong>'+machines.filter(m=>m.status==='repair').length+'</strong></div><div class="status-card"><span>Активные заявки</span><strong>'+active.length+'</strong></div><div class="status-card"><span>Уточнить продление (5 ч)</span><strong>'+pending.length+'</strong></div></div><p class="page-note">Свободно — без активного бронирования и блокирующего ремонта. Данные демонстрационные и локальные.</p><button class="btn primary" data-nav="requests">Открыть заявки и календарь</button></section>';}
function requestsPage(){
 const rows=requestList(),today=new Date().toISOString().slice(0,10),soon=new Date(Date.now()+86400000).toISOString().slice(0,10);
 const pending=rows.filter(requestNeedsFollowup);
 const days=Array.from({length:14},(_,i)=>{let d=new Date(Date.now()+i*86400000);return d.toISOString().slice(0,10)});
 const assignments=rows.filter(requestIsActive).flatMap(r=>r.items.map(x=>({...x,request:r})));
 const calendar='<section class="panel"><div class="panel-head"><h2>Календарь занятости · 14 дней</h2></div><div class="table-scroll"><table class="data-table" style="font-size:12px"><thead><tr><th>Техника</th>'+days.map(d=>'<th title="'+d+'">'+d.slice(5)+'</th>').join('')+'</tr></thead><tbody>'+machines.map(m=>'<tr><td>'+esc(m.name)+'</td>'+days.map(d=>{const a=assignments.find(x=>x.machine===m.id&&x.start.slice(0,10)<=d&&x.end.slice(0,10)>=d);const blocked=m.status==='repair';return '<td title="'+esc(a?a.request.number+' · '+a.request.object+' · '+a.operator:blocked?'На ремонте':'Свободно')+'" style="text-align:center;'+(a?'background:#dbeafe;':blocked?'background:#ffedd5;':'')+'">'+(a?'<button class="btn small" data-request-open="'+esc(a.request.id)+'">●</button>':blocked?'Р':'·')+'</td>'}).join('')+'</tr>').join('')+'</tbody></table></div></section>';
 return '<section class="panel"><div class="panel-head"><h2>Контроль заявок</h2></div><p>Всего заявок: <b>'+rows.length+'</b> · Требуют уточнения срока: <b>'+pending.length+'</b></p>'+pending.map(r=>'<p>Срок заканчивается: '+esc(r.number)+' · '+esc(r.customer)+' <button class="btn small" data-request-open="'+esc(r.id)+'">Продлить / уточнить</button></p>').join('')+'</section>'+calendar+
 '<section class="panel"><div class="panel-head"><h2>Заявки на технику</h2></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Номер</th><th>Заказчик / объект</th><th>Назначения</th><th>Статус / контроль</th><th></th></tr></thead><tbody>'+rows.slice().reverse().map(r=>'<tr><td>'+esc(r.number)+'</td><td>'+esc(r.customer)+' · '+esc(r.object)+'</td><td>'+r.items.map(x=>esc(machine(x.machine)?.name||x.machine)+' — '+esc(x.operator)+' ('+esc(x.start)+' — '+esc(x.end)+')').join('<br>')+'</td><td>'+esc(r.status)+' · '+esc(r.dispatchStage||'Этап не указан')+(r.releaseConfirmed?' · освобождена':'')+(r.followup?' · '+esc(r.followup):'')+'</td><td><button class="btn small" data-request-open="'+esc(r.id)+'">Открыть</button></td></tr>').join('')+'</tbody></table></div></section>';
}
const requestAuditFields={dispatchStage:'Этап исполнения',customer:'Заказчик',object:'Объект',comment:'Комментарий',contact:'Контакт',phone:'Телефон',followup:'Результат уточнения',arrival:'Выход техники',releaseConfirmed:'Освобождение подтверждено',status:'Статус'};
const requestItemText=x=>x?[(machine(x.machine)?.name||x.machine),x.operator,x.start,x.end].join(' / '):'—';
function requestChanges(before,after){
 const changes=[];
 for(const [key,label] of Object.entries(requestAuditFields)){const a=String(before?.[key]??'—'),b=String(after?.[key]??'—');if(a!==b)changes.push({field:label,from:a,to:b});}
 const a=before?.items||[],b=after.items||[];
 for(let i=0;i<Math.max(a.length,b.length);i++){if(JSON.stringify(a[i]||null)!==JSON.stringify(b[i]||null))changes.push({field:'Назначение №'+(i+1),from:requestItemText(a[i]),to:requestItemText(b[i])});}
 return changes;
}
function requestHistoryHtml(r){return '<section style="margin-top:18px"><h3>Журнал изменений</h3>'+(r.history||[]).slice().reverse().map(h=>'<div style="border-bottom:1px solid #ddd;padding:10px 0"><b>'+esc(h.by||'Неизвестно')+'</b> · '+esc(new Date(h.at).toLocaleString('ru-RU'))+'<br>'+esc(h.action||'Изменение')+'<br>Причина: '+esc(h.reason||'Не указана')+(h.changes||[]).map(c=>'<div><b>'+esc(c.field)+':</b> '+esc(c.from)+' → '+esc(c.to)+'</div>').join('')+'</div>').join('')+'</section>';}
function requestModal(id){if(!['director','dispatcher'].includes(role))return;const old=requestList().find(r=>r.id===id);const item=x=>'<div class="request-item" style="padding:12px;border:1px solid #ddd;margin:8px 0"><label>Техника<select name="machine" required><option value="">Выберите технику</option>'+machines.map(m=>'<option value="'+esc(m.id)+'" '+(x?.machine===m.id?'selected':'')+(m.status==='repair'?' disabled':'')+'>'+esc(m.name)+' · '+esc(m.id)+' · '+esc(m.type)+' · '+esc(obj(m.object)?.name||'')+(m.status==='repair'?' · НА РЕМОНТЕ':'')+'</option>').join('')+'</select></label><label>Машинист<select name="operator" required><option value="">Выберите машиниста</option>'+[...new Set(machines.map(m=>m.operator))].map(n=>'<option '+(x?.operator===n?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select></label><label>Начало<input type="datetime-local" name="start" required value="'+esc(x?.start||'')+'"></label><label>Окончание<input type="datetime-local" name="end" required value="'+esc(x?.end||'')+'"></label><button type="button" class="btn request-remove">Убрать</button></div>';
showModal(old?'Редактировать заявку':'Создать заявку','<form id="request-form"><p>Ответственный менеджер: <b>'+esc(old?.owner||currentManager())+'</b></p><label>Заказчик<input name="customer" required maxlength="120" value="'+esc(old?.customer||'')+'"></label><label>Объект<select name="object" required>'+objects.map(o=>'<option '+(old?.object===o.name?'selected':'')+'>'+esc(o.name)+'</option>').join('')+'</select></label><label>Комментарий<textarea name="comment" maxlength="500">'+esc(old?.comment||'')+'</textarea></label><label>Контакт заказчика<input name="contact" maxlength="120" value="'+esc(old?.contact||'')+'"></label><label>Телефон<input name="phone" maxlength="40" value="'+esc(old?.phone||'')+'"></label><label>Результат уточнения<select name="followup">'+['Не уточняли','Ожидается ответ','Продление согласовано','Завершение согласовано'].map(v=>'<option '+(old?.followup===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>Фактический выход<select name="arrival">'+['Запланирована','Прибыла на объект','Приступила к работе'].map(v=>'<option '+(old?.arrival===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>Этап исполнения<select name="dispatchStage">'+['Назначена','Готовится к отправке','На объекте','Возвращается','Освобождена'].map(v=>'<option '+(old?.dispatchStage===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label><input type="checkbox" name="releaseConfirmed" '+(old?.releaseConfirmed?'checked':'')+'> Фактическое освобождение подтверждено</label><h3>Назначения</h3><div id="request-items">'+(old?.items||[null]).map(item).join('')+'</div><button type="button" class="btn" id="request-add">Добавить технику</button><label>Статус<select name="status">'+['Новая','Назначена','В работе','Завершена','Отменена'].map(v=>'<option '+(old?.status===v?'selected':'')+'>'+v+'</option>').join('')+'</select></label><label>Причина изменения (обязательно при редактировании)<textarea name="changeReason" maxlength="500" '+(old?'required':'')+' placeholder="Что изменилось и почему"></textarea></label><div class="modal-actions"><button class="btn primary" type="submit">Сохранить</button></div></form>',true);
$('#request-add').onclick=()=>$('#request-items').insertAdjacentHTML('beforeend',item(null));
$('#request-items').onclick=e=>{if(e.target.classList.contains('request-remove')&&document.querySelectorAll('.request-item').length>1)e.target.closest('.request-item').remove();};
$('#request-form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),items=[...document.querySelectorAll('.request-item')].map(el=>{const v=n=>el.querySelector('[name="'+n+'"]').value;return {machine:v('machine'),operator:v('operator'),start:v('start'),end:v('end')};});
if(items.some(x=>!x.machine||!x.operator||!x.start||!x.end||x.start>=x.end))return toast('Проверьте назначения и даты.');
if(fd.get('status')!=='Отменена'&&items.some(x=>machine(x.machine)?.status==='repair'))return toast('Назначение запрещено: техника на ремонте. Ожидайте подтверждения готовности механиком.');
if(fd.get('dispatchStage')==='Освобождена'&&!fd.has('releaseConfirmed'))return toast('Для освобождения техники подтвердите фактический возврат.');
if(old&&!String(fd.get('changeReason')||'').trim())return toast('Укажите причину изменения заявки.');
// Finished requests continue to reserve equipment until its actual release is confirmed.
const active=requestList().filter(r=>r.id!==old?.id&&r.status!=='Отменена'&&!r.releaseConfirmed).flatMap(r=>(r.items||[]).map(x=>({...x,requestNumber:r.number})));
if(fd.get('status')!=='Отменена'&&!fd.has('releaseConfirmed')){
for(let i=0;i<items.length;i++){const a=items[i];const conflicts=[...active,...items.filter((_,j)=>i!==j).map(x=>({...x,requestNumber:'текущая заявка'}))];
const clash=conflicts.find(b=>a.start<b.end&&b.start<a.end&&(a.machine===b.machine||a.operator===b.operator));
if(clash)return toast('Двойное назначение: '+(a.machine===clash.machine?'техника '+(machine(a.machine)?.name||a.machine):'машинист '+a.operator)+' уже занята ('+clash.requestNumber+').');}
}
const before=old?JSON.parse(JSON.stringify(old)):null;const reason=String(fd.get('changeReason')||'').trim();const r=old||{owner:currentManager(),history:[],id:'req-'+Date.now(),number:'ЗТ-'+String(requestList().length+1).padStart(4,'0')};Object.assign(r,{dispatchStage:fd.get('dispatchStage'),customer:String(fd.get('customer')).trim(),object:fd.get('object'),comment:fd.get('comment'),contact:fd.get('contact'),phone:fd.get('phone'),followup:fd.get('followup'),arrival:fd.get('arrival'),releaseConfirmed:fd.has('releaseConfirmed'),status:fd.get('status'),items});if(!old)requestList().push(r);r.history=Array.isArray(r.history)?r.history:[];const changes=requestChanges(before,r);if(!old||changes.length)r.history.push({by:currentManager(),at:new Date().toISOString(),action:old?'Изменение заявки':'Создание заявки',reason:reason||'Первичное оформление',changes});persist();closeModal(false);render();toast('Заявка сохранена.');};}

function approveShift(id){if(!canApprove())return;const s=state.shifts.find(s=>s.id===id);if(!s||s.status!=='pending')return;const maxNumber=Math.max(0,...state.shifts.map(x=>Number((x.waybill||'').replace('ПЛ-',''))||0));s.status='approved';s.waybill='ПЛ-'+String(maxNumber+1).padStart(4,'0');s.approvedAt=new Date().toISOString();const saved=persist();render();if(saved)toast('Смена утверждена. Табель и черновик путевого листа обновлены.');}
function returnShiftModal(id){const s=state.shifts.find(s=>s.id===id);if(!canApprove()||!s||s.status!=='pending')return;showModal('Вернуть смену машинисту',`<form id="return-form">${field('Что нужно исправить?','<textarea name="reason" required maxlength="250" placeholder="Укажите причину возврата"></textarea>')}${formActions('Вернуть смену')}</form>`);$('#return-form').onsubmit=e=>{e.preventDefault();const reason=new FormData(e.target).get('reason').trim();if(!reason)return formError('Укажите причину возврата.');s.status='returned';s.returnNote=reason;const saved=persist();closeModal(false);render();if(saved)toast('Смена возвращена на исправление.');};}
function waybillModal(id){const s=state.shifts.find(s=>s.id===id);if(!s||s.status!=='approved')return;const m=machine(s.machine);showModal('Черновик путевого листа',`<div class="print-title">ООО «МонАрх и М»</div>${tag('Демонстрационный черновик','orange')}<h2 class="section-gap">Путевой лист ${esc(s.waybill)}</h2><dl class="spec-grid"><div><dt>Дата</dt><dd>${dateText(s.date)}</dd></div><div><dt>Техника</dt><dd>${esc(m.name)} · ${m.id}</dd></div><div><dt>Машинист</dt><dd>${esc(m.operator)}</dd></div><div><dt>Объект</dt><dd>${esc(obj(m.object).name)}</dd></div><div><dt>Отработано</dt><dd>${s.hours} ч</dd></div><div><dt>Счётчик при закрытии</dt><dd>${s.meter} м/ч</dd></div><div><dt>Состояние</dt><dd>${s.condition==='ok'?'Исправна':'Есть замечание'}</dd></div><div><dt>Статус смены</dt><dd>Утверждена</dd></div></dl><p>Комментарий: ${esc(s.note||'Замечаний нет')}</p><div class="info-note">Демонстрационный документ. Полная форма, медосмотр, технический контроль, подписи и иные обязательные реквизиты в этом черновике не оформлены.</div><div class="modal-actions"><button class="btn" data-close>Закрыть</button><button class="btn primary" id="print-waybill">${icon('print')}Печать</button></div>`,true);$('#print-waybill').onclick=()=>window.print();}
function serviceModal(){repairForm();}
function syncMachineStatuses(){for(const m of machines)m.status=state.maintenance.some(r=>r.machine===m.id&&r.blocking&&!r.readyConfirmed)?'repair':'work';}
function completeService(id){openRepair(id);}
function stockModal(){showModal('Движение запчастей',`<form id="stock-form">${field('Наименование',`<select name="part">${state.stock.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.qty} ${esc(p.unit)}</option>`).join('')}</select>`)}<div class="form-grid">${field('Операция','<select name="kind"><option value="receipt">Поступление на склад</option><option value="issue">Выдача на технику</option></select>')}${field('Количество','<input name="qty" type="number" min="0.01" max="1000000" step="0.01" inputmode="decimal" required>')}</div><div class="field section-gap"><label>Техника при выдаче<select name="machine"><option value="">Не выбрана</option>${machines.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label></div>${field('Дата',`<input name="date" type="date" value="${today()}" required>`)}${field('Комментарий','<textarea name="note" maxlength="200"></textarea>')}${formActions()}<p class="form-hint">Движение меняет количество на складе. Финансовую стоимость при необходимости внесите отдельной операцией.</p></form>`);$('#stock-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=state.stock.find(p=>p.id===f.get('part')),qty=Number(f.get('qty')),kind=f.get('kind'),id=f.get('machine');if(!Number.isFinite(qty)||qty<=0)return formError('Укажите положительное количество.');if(p.unit==='шт.'&&!Number.isInteger(qty))return formError('Для штучной позиции укажите целое количество.');if(kind==='issue'&&!id)return formError('Выберите технику, на которую выдаются запчасти.');if(kind==='issue'&&qty>p.qty)return formError('Недостаточно на складе. Доступно: '+p.qty+' '+p.unit);p.qty=Math.round((p.qty+(kind==='receipt'?qty:-qty))*100)/100;state.stockMoves.push({id:uid(),part:p.id,qty,kind,machine:kind==='issue'?id:'',date:f.get('date'),note:f.get('note').trim()});const saved=persist();closeModal(false);render();if(saved)toast(kind==='receipt'?'Поступление добавлено. Остаток обновлён.':'Запчасти выданы. Остаток обновлён.');};}
function deleteOperationModal(id){if(role!=='director')return;const op=state.operations.find(o=>o.id===id);if(!op||op.source==='excel-demo'||op.sourceRepair)return;showModal('Удалить операцию?',`<p>${esc(op.category)} · ${rub(op.amount)}<br>${esc(machine(op.machine).name)} · ${dateText(op.date)}</p><p class="section-gap">Запись будет удалена из демонстрационного журнала, показатели пересчитаются.</p><div class="modal-actions"><button class="btn" data-close>Отмена</button><button class="btn danger" id="confirm-delete">Удалить</button></div>`);$('#confirm-delete').onclick=()=>{const previous=structuredClone(state);state.operations=state.operations.filter(o=>o.id!==id);const saved=persist();if(!saved){state=previous;return formError('Не удалось сохранить удаление.');}closeModal(false);render();toast('Операция удалена. Показатели пересчитаны.');};}
function resetModal(){if(role!=='director')return;showModal('Сбросить демонстрацию?',`<p>Добавленные операции, смены, задачи и движения склада в этом браузере будут удалены. Восстановится исходный пример с 10 единицами техники.</p><div class="modal-actions"><button class="btn" data-close>Отмена</button><button class="btn danger" id="confirm-reset">Сбросить данные</button></div>`);$('#confirm-reset').onclick=()=>{state=initialState();initializeWorkshop();syncMachineStatuses();const saved=persist();closeModal(false);render();if(saved)toast('Исходные демонстрационные данные восстановлены.');};}
function download(name,content,type){const blob=new Blob([content],{type:type+';charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(value){let s=String(value??'');if(typeof value==='string'&&/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportData(type){let rows=[],name=type;if(type==='finance'&&!canFinance())return;if(type==='fleet'&&!canFinance())return;if(type==='finance')rows=[['Дата','Техника','Инв. номер','Объект','Тип','Статья','Сумма, ₽','Комментарий','Демо'],...operations().map(o=>[o.date,machines.some(m=>m.id===o.machine)?machine(o.machine).name:(o.allocation==='overhead'?'Общехозяйственные':'Не распределено'),o.machine||'',machines.some(m=>m.id===o.machine)?obj(machine(o.machine).object).name:'—',o.kind==='income'?'Доход':'Расход',o.category,o.amount,o.note,'Да'])];if(type==='fleet')rows=[['Техника','Инв. номер','Объект','Выручка, ₽','Расходы, ₽','Результат, ₽','Маржа, %','Демо'],...machines.map(m=>{const s=sums([m]);return [m.name,m.id,obj(m.object).name,s.income,s.expense,s.income-s.expense,s.income?((s.income-s.expense)/s.income*100).toFixed(2):'','Да'];})];if(type==='timesheets'){const ss=visibleShifts().filter(s=>s.status==='approved');rows=[['Машинист','Техника','Объект','Смен','Часов','Демо'],...visibleMachines().filter(m=>ss.some(s=>s.machine===m.id)).map(m=>{const list=ss.filter(s=>s.machine===m.id);return [m.operator,m.name,obj(m.object).name,list.length,list.reduce((n,s)=>n+s.hours,0),'Да'];})];}if(type==='waybills')rows=[['Номер','Дата','Техника','Инв. номер','Машинист','Объект','Часов','Счётчик','Демо'],...visibleShifts().filter(s=>s.status==='approved').map(s=>[s.waybill,s.date,machine(s.machine).name,s.machine,machine(s.machine).operator,obj(machine(s.machine).object).name,s.hours,s.meter,'Да'])];if(!rows.length)return;download(`monarch-im-${name}-${period}.csv`,'\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv');toast('Отчёт скачан в формате CSV.');}
document.addEventListener('keydown',e=>{const modal=$('.modal');if(e.key==='Escape'&&modal){e.preventDefault();closeModal();}if(e.key==='Tab'&&modal){const list=[...modal.querySelectorAll('button:not([disabled]),input,select,textarea,[href],[tabindex="0"]')].filter(el=>el.offsetParent!==null);const first=list[0],last=list[list.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===modal)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}if(e.key==='/'&&!modal&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){$('#global-search')?.focus();e.preventDefault();}});
initializeWorkshop();
syncMachineStatuses();
render();
